class Record:
    def __init__(self, record_id, parent_id):
        self.record_id = record_id
        self.parent_id = parent_id


class Node:
    def __init__(self, node_id):
        self.node_id = node_id
        self.children = []


def BuildTree(records):
    count = len(records)
    if count == 0:
        return None

    nodes = [None] * count
    parent_of = [None] * count

    for record in records:
        node_id = record.record_id
        parent_id = record.parent_id

        if not isinstance(node_id, int) or not isinstance(parent_id, int):
            raise ValueError("record IDs must be integers")
        if node_id < 0 or node_id >= count:
            raise ValueError("record ID out of range")
        if nodes[node_id] is not None:
            raise ValueError("duplicate record ID")

        if node_id == 0:
            if parent_id != 0:
                raise ValueError("root must be its own parent")
        elif parent_id < 0 or parent_id >= node_id:
            raise ValueError("invalid parent ID")

        nodes[node_id] = Node(node_id)
        parent_of[node_id] = parent_id

    if any(node is None for node in nodes):
        raise ValueError("record IDs must be contiguous")

    for node_id in range(1, count):
        nodes[parent_of[node_id]].children.append(nodes[node_id])

    return nodes[0]

